import React, { useEffect, useState } from "react";
import { useParams, useSearchParams } from "react-router-dom";  // Added useSearchParams
import "./Profile.css";

const Profile = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  const { itemId } = useParams();  // Extract itemId from path, e.g., /profile/1489?type=project
  const [searchParams] = useSearchParams();
  const type = searchParams.get('type');  // Extract type from query params

  useEffect(() => {
    if (!itemId || !type) {
      setError("Invalid URL parameters");
      setLoading(false);
      return;
    }

    const fetchProfile = async () => {
      try {
        // If authentication is required, add headers here (e.g., Authorization: `Bearer ${token}`)
        const response = await fetch(`/api/profile/${itemId}?type=${type}`);
        if (!response.ok) {
          throw new Error(`Error: ${response.status} ${response.statusText}`);
        }
        const result = await response.json();
        setData(result);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, [itemId, type]);

  if (loading) return <p style={{ padding: "20px" }}>Loading profile details...</p>;
  if (error) return <p style={{ padding: "20px", color: "red" }}>Error: {error}</p>;
  if (!data) return <p style={{ padding: "20px" }}>No data available</p>;

  // Helper to format field names (e.g., "required_skills" -> "Required Skills")
  const formatFieldName = (key) => {
    return key
      .replace(/_/g, ' ')
      .replace(/\b\w/g, (l) => l.toUpperCase());
  };

  return (
    <div className="profile-container">
      <h1 className="profile-title">{data.type} Profile</h1>
      <div className="profile-card">
        {Object.entries(data.data).map(([key, value]) => (
          <p key={key}>
            <b>{formatFieldName(key)}:</b> {Array.isArray(value) ? value.join(", ") : value}
          </p>
        ))}
      </div>
    </div>
  );
};

export default Profile;
